import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = next(iterator)
            B = next(iterator)
        except StopIteration:
            break

        current_A = list(A)

        impossible = False
        for i in range(N):
            if current_A[i] > B[i]:
                impossible = True
                break

        if impossible:
            print("-1")
            continue

        if current_A == list(B):
            print("0")
            continue

        operations = []
        unique_chars_needed = sorted(set(B))

        for target_char in unique_chars_needed:
            indices_to_change = []
            for i in range(N):
                if current_A[i] != target_char and B[i] == target_char:
                    indices_to_change.append(i)

            if not indices_to_change:
                continue

            min_char_in_set = min(current_A[i] for i in indices_to_change)

            if min_char_in_set > target_char:
                impossible = True
                break

            if min_char_in_set != target_char:
                pass

            for i in indices_to_change:
                current_A[i] = target_char

            operations.append(indices_to_change)

        if impossible:
            print("-1")
        else:
            print(len(operations))
            for op_indices in operations:
                op_str = " ".join(map(str, op_indices))
                print(f"{len(op_indices)} {op_str}")

if __name__ == "__main__":
    solve()
